  "Ko'chirishni tahrirlash": "Edit reschedule",
  "Ko'chirishni o'chirish": "Delete reschedule",
  "O'rinbosarni o'chirish": "Delete substitute",
  "Bekor qilishni o'chirish": "Delete cancellation",
  // Groups — the lesson changes tab
  "O'chirishda xatolik": "Error while deleting",
  "Bekor qilingan dars yozuvini o'chirmoqchimisiz?": "Delete the record of the cancelled lesson?",
  "Bekor qilishda o'quvchilarga qaytarilgan dars puli ulardan qayta yechiladi; shundan beri muzlatilgan yoki guruhdan chiqqan o'quvchining puli qoladi. Davomat tiklanmaydi. Agar dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "The lesson money that was returned to students when the lesson was cancelled is charged to them again; a student who has since been frozen or has left the group keeps the money. Attendance is not restored. If the lesson time has already passed, the lesson returns to the “Did the lesson take place?” question.",
  "Bekor qilingan dars yozuvi o'chirildi": "The record of the cancelled lesson was deleted",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi, {kept} o'quvchida qoldi": "Cancellation deleted. Charged again: {amount} UZS (students: {n}). Money stayed with students: {kept}",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi": "Cancellation deleted. Charged again: {amount} UZS (students: {n})",
  "O'rinbosar ustoz qoidasini bekor qilmoqchimisiz?": "Cancel the substitute teacher assignment?",
  "Oddiy guruh ustozlariga qaytariladi va ularning oyligi qayta hisoblanadi.": "The lesson goes back to the group's regular teachers and their salary is recalculated.",
  "O'rinbosar bekor qilindi": "Substitute cancelled",
  "Ko'chirish yozuvini o'chirmoqchimisiz?": "Delete the reschedule record?",
  "Diqqat: bu ikkala sanada (asl va yangi) davomatni avtomatik tiklamaydi. Agar asl dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "Note: attendance is not restored automatically on either date (the original or the new one). If the original lesson time has already passed, the lesson returns to the “Did the lesson take place?” question.",
  "Ko'chirish yozuvi o'chirildi": "The reschedule record was deleted",
  "Sana va sababni kiriting": "Enter the date and the reason",
  "Dars bekor qilindi": "The lesson was cancelled",
  "Bekor qilishda xatolik": "Error while cancelling",
  "Agar bu kuni davomat allaqachon olingan bo'lsa, har bir o'quvchining holati \"uzrli sabab bilan kelmadi\" ga o'tadi va undan yechilgan pul qaytariladi (qoldiq darslar hisobi 1 ga oshadi).": "If attendance was already taken on this day, each student's status changes to “absent with a valid reason” and the money charged to them is returned (the count of remaining lessons goes up by 1).",
  "Bekor qilinadigan dars sanasi": "Date of the lesson to cancel",
  "Faqat ushbu guruh dars qiladigan sanalar ko'rinadi": "Only dates when this group has lessons are shown",
  "Ustoz kasal, bayram, va h.k.": "Teacher is sick, holiday, etc.",
  "Kamida 1 ta ustoz bo'lishi kerak": "There must be at least one teacher",
  "O'rinbosar saqlandi": "Substitute saved",
  "Saqlashda xatolik": "Error while saving",
  "Darsga o'rinbosar ustoz tayinlash": "Assign a substitute teacher to the lesson",
  "Tanlangan kungi dars uchun ustozlarni almashtiring. Agar bu kuni davomat allaqachon olingan bo'lsa, oylik avtomatik qayta hisoblanadi (eski ustozlardan olib tashlanib, yangilarga yoziladi).": "Replace the teachers for the lesson on the chosen day. If attendance was already taken on this day, the salary is recalculated automatically (removed from the previous teachers and credited to the new ones).",
  "Dars sanasi": "Lesson date",
  "Ushbu guruh dars qiladigan kunlar; ko'chirilgan sanalar ham ro'yxatda chiqadi": "Days when this group has lessons; rescheduled dates also appear in the list",
  "Bu darsni o'tadigan ustozlar": "Teachers of this lesson",
  "Odatda: guruhning {n} ta standart ustozi. Tanlovni o'zgartirsangiz, faqat tanlanganlarga oylik yoziladi.": "Default: the group's standard teachers: {n}. If you change the selection, salary is credited only to those selected.",
  "Sabab (ixtiyoriy)": "Reason (optional)",
  "Masalan 'Botir kasal'": "For example “Botir is sick”",
  "Bo'sh xonalarni olishda xatolik": "Error while loading free rooms",
  "Asl va yangi sanani tanlang": "Pick the original and the new date",
  "Yangi sana asl sanadan keyin bo'lishi kerak": "The new date must be after the original date",
  "Dars boshlanish vaqtini kiriting": "Enter the lesson start time",
  "Bo'sh xonani tanlang": "Pick a free room",
  "Ko'chirilgan dars yangilandi": "The rescheduled lesson was updated",
  "Ko'chirishda xatolik": "Error while rescheduling",
  "Ko'chirilgan darsni tahrirlash": "Edit the rescheduled lesson",
  "Darsni boshqa kunga ko'chirish": "Move the lesson to another day",
  "Asl sana o'zgartirib bo'lmaydi (audit yozuvi). Yangi sana, vaqt, xona va sababni o'zgartirishingiz mumkin.": "The original date cannot be changed (audit record). You can change the new date, time, room and reason.",
  "Bu kungi dars yangi sanaga o'tkaziladi. Asl kunda davomat olingan bo'lsa, to'lov va oylik avtomatik qaytariladi.": "This day's lesson is moved to the new date. If attendance was already taken on the original day, the payment and salary are returned automatically.",
