  "Faol vaqt: ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan. Radio bunga kirmaydi.": "Active time: the app is open on the screen and the student has done something in the last 2 minutes. Radio is not included.",
  "birinchi urinishda · {n} savol": "on the first try · questions: {n}",
  "Har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi.": "A question counts when it was answered correctly the first time it was asked. An answer to the question asked again after a mistake is not part of this percentage.",
