  "Davrda oxirigacha ishlangan turli darslar. Bitta darsni qayta ishlash qo'shimcha sanalmaydi.": "Different lessons worked through to the end in the period. Doing the same lesson again is not counted extra.",
  "{n} o'quvchi tingladi": "Listened: {n}",
  "Ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, lekin faol vaqtga qo'shilmaydi.": "The time the sound actually played. It counts even when the screen is off, but is not added to active time.",
  // Groups — app activity table
  "Shug'ullangan kunlar": "Practice days",
  "Shu kuni kamida bitta mashq qildi yoki kamida 5 daqiqa radio tingladi": "On that day the student did at least one exercise or listened to the radio for at least 5 minutes",
