  // Groups — app activity explainer
  "Raqamlar qanday hisoblanadi": "How the numbers are calculated",
  "ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan vaqt. Ochiq qoldirilgan tab sanalmaydi.": "the app is open on the screen and the student has done something in the last 2 minutes. A tab left open does not count.",
  "ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, faol vaqtga qo'shilmaydi.": "the time the sound actually played. It counts even when the screen is off, but is not added to active time.",
  "kamida bitta mashq javobi yoki kamida 5 daqiqa radio. Faqat ilovani ochish sanalmaydi.": "at least one exercise answer or at least 5 minutes of radio. Just opening the app does not count.",
  "Kunlar maxraji": "Day denominator",
  "o'quvchi akkaunti yaratilgan yoki kuzatuv boshlangan kundan sanaladi.": "counted from the day the student's account was created or tracking began.",
  "Kuzatuv {date} dan boshlangan.": "Tracking started on {date}.",
  "har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi. O'quvchi natija ekranida ko'radigan raqam bilan bir xil ta'rif.": "a question counts when it was answered correctly the first time it was asked. An answer to the question asked again after a mistake is not part of this percentage. Same definition as the number the student sees on the result screen.",
  "darajadagi kurs darslaridan tugatilganlari; o'quvchi darajasi guruhnikidan past bo'lsa «Guruhdan orqada» belgisi.": "completed course lessons at this level; if the student's level is below the group's, the «Behind the group» mark appears.",
