  "{month}: {amount}": "{month}: {amount}",
  "{month} (davom etmoqda): {amount}": "{month} (in progress): {amount}",
  "Har oy to'liq ishlangan pul — «Ish haqi» bo'limidagi raqamning o'zi.\nJoriy oy hali tugamagan: raqam oy oxirigacha o'sadi.": "Money fully earned each month — the same figure as in the “Salary” section.\nThe current month is not over yet: the figure grows until the end of the month.",
  "Bu oylarda oylik yo'q": "No salary in these months",
  "Oylik": "Salary",
  "Hozir: {n} nafar": "Now: {n} students",
  "Har oy oxirida ustoz guruhlarida o'qiyotgan o'quvchilar soni.\nGuruh boshqa ustozga o'tgan oydan boshlab sanalmaydi.": "Number of students studying in the teacher's groups at the end of each month.\nThey are not counted from the month the group passes to another teacher.",
  "Kelganlar va ketganlar": "Joined and left",
  "{month}: +{joined} qo'shildi, −{left} ketdi": "{month}: +{joined} joined, −{left} left",
  "Yashil — ustoz guruhiga qo'shilganlar (boshqa guruhdan o'tganlar ham).\nQizil — markazdan ketganlar («Ketganlar» hisobotidagi qoida).\nOch qizil — to'xtagan, lekin hali qaytishi mumkin (21 kun, muzlatishda 60 kun).": "Green — joined the teacher's group (including those who moved from another group).\nRed — left the center (the rule of the “Departed” report).\nLight red — stopped coming but may still return (21 days, 60 days when frozen).",
  "Bu oylarda kelgan ham, ketgan ham yo'q": "Nobody joined or left in these months",
  "Qaytishi mumkin": "May return",
  "{month}: {pct}%": "{month}: {pct}%",
  "Kelgan va kechikkanlar ÷ (kelgan + kechikkan + kelmagan).\nSababli va bekor qilingan darslar hisobga olinmaydi.": "Present and late ÷ (present + late + absent).\nExcused and cancelled lessons are not counted.",
  "Bu oylarda davomat olinmagan": "No attendance was taken in these months",
  "Hech qanday muhim o'zgarish topilmadi": "No significant changes found",
  "{month} — bu oy qo'lda kiritilgan, har bir dars bo'yicha ma'lumot yo'q. Faqat kiritilgan summa va avans ko'rsatilgan.": "{month} — this month was entered manually, with no data for individual lessons. Only the entered amount and the advance are shown.",
  "{month} uchun oylik ma'lumoti yo'q — boshqa oyni tanlab ko'ring.": "No salary data for {month} — try another month.",
  "To'lanishi kerak": "Amount due",
  "Bu oy uchun to'lanishi kerak bo'lgan sof summa: to'liq ishlangan (markaz qo'shimchasi bilan) − avans. Hisoblab bo'lingan oylar uchun haqiqiy to'langan summa ko'rsatiladi.": "Net amount due for this month: fully earned (including the center top-up) − advance. For months already calculated, the amount actually paid is shown.",
  "Oylik (belgilangan)": "Salary (fixed)",
  "Avans": "Advance",
  "To'liq ishlangan": "Fully earned",
  "O'quvchilar to'lagan": "Paid by students",
  "To'liq ishlangandan o'quvchilar haqiqatan to'lagani bilan qoplangan qismi.": "The part of the fully earned amount covered by what students actually paid.",
  "Markaz qo'shimchasi": "Center top-up",
  "Markazning o'z hisobidan qo'shgan (yoki oy yopilgunicha qo'shadigan) qismi. Oy yopilgach bu raqam qolaveradi — o'quvchi keyin to'lasa, pul markazga qaytadi, ustozga qayta yozilmaydi. Oylik to'lov kurslarida o'quvchi hali to'lamagan oylik hisobining ulushi ham shu yerda — u to'lagan sari kamayadi.": "The part the center added from its own funds (or will add before the month closes). Once the month is closed this figure stays: if the student pays later, the money returns to the center and is not credited to the teacher again. For monthly-payment courses it also includes the share of the monthly charge the student has not paid yet — it shrinks as they pay.",
  "Shu oy ichida ustozga oldindan berilgan pul (Xarajatlar → Avans). U «To'lanishi kerak»dan allaqachon ayirilgan.": "Money paid to the teacher in advance during this month (Expenses → Advance). It has already been subtracted from “Amount due”.",
  "Shu oy uchun to'lanishi kerak bo'lgan sof summa — avans allaqachon ayirilgan. «Ish haqi» bo'limidagi va Moliya → Oyliklar sahifasidagi raqam bilan bir xil.": "Net amount due for this month — the advance has already been subtracted. The same figure as in the “Salary” section and on the Finance → Salaries page.",
  "Ishlangan {amount}": "Earned {amount}",
  "avans −{amount}": "advance −{amount}",
