  "Ustozlarga avans — Ish haqi → Avanslar bo'limida. Xodimlar oyligi — Ish haqida; bu yerga yozilmaydi, aks holda foydadan ikki marta ayiriladi.": "Teacher advances are under Salary → Advances. Staff pay is under Salary; do not record it here, or it is deducted from the profit twice.",
