  "Reklama qaysi kanal uchun bo'lsa, shuni tanlang — hisobotda shu kanalning o'quvchisi narxi chiqadi.": "Pick the channel the advertising was for — the report will show what one student of that channel cost.",
  // Payments — debt («Qarzdorlik»)
  "Muzlatilganlarning markazda turgan puli — {page} sahifasida.": "Money of frozen students held by the center is on the {page} page.",
