  "{month} to'lovini hali to'liq to'lamagan o'qiyotgan o'quvchilar. To'lov muddati — shartnoma bo'yicha oyning 2-darsigacha.": "Current students who have not yet paid {month} in full. Under the contract, payment is due by the 2nd lesson of the month.",
  "O'qiyotgan, lekin o'tgan oylardan qarzi qolgan o'quvchilar. Shartnomaga ko'ra 2-darsga kirish uchun eski qarz ham to'lanishi kerak.": "Current students with debt left from past months. Under the contract, old debt must also be paid to attend the 2nd lesson.",
  "Hozir hech qaysi guruhda o'qimayotganlar: guruhsiz qolgan, muzlatilgan yoki ketgan. Bu — undirish ro'yxati: qo'ng'iroq, va'da, to'lov.": "Not studying in any group now: left without a group, frozen or gone. This is the collection list: call, promise, payment.",
