  "Barcha qarzdorlar — hozir o'qiyotgani ham, ketgani ham.": "All debtors — both current students and those who left.",
  "Qarz oyma-oy qanday o'zgargan: qancha qo'shilgan, qanchasi to'langan va oy oxirida qancha qolgan.": "How the debt changed month by month: how much was added, how much was paid and how much was left at the end of the month.",
  "Butun kompaniya bo'yicha — bu jadval filialga bo'linmaydi.": "For the whole company — this table is not split by branch.",
  "O'quvchi o'qishni tashlagani uchun undirilmaydigan deb belgilangan qarzlar.": "Debts marked as uncollectable because the student dropped out.",
  "Markaz o'quvchilar to'lamagan darslar uchun ustozlarga pul to'lab bergan. Bu yerda o'sha pul kimdan undirilishi kerakligi ko'rinadi.": "The center paid teachers for lessons students did not pay for. This shows who that money must be collected from.",
  "Davr tanlovi qaysi oydagi darslar hisobga olinishini belgilaydi — o'quvchining qarz summasi o'zgarmaydi.": "The period choice decides which month's lessons count — the student's debt amount does not change.",
  "Butun davr": "Whole period",
  "Markaz qoplagan, hali qaytmagan dars yo'q — hammasi undirilgan.": "No lessons covered by the center are still outstanding — everything has been collected.",
  "{month}da markaz qoplagan dars yo'q — bu oyda hali dars o'tilmagan yoki hamma o'quvchi to'lagan.": "No lessons covered by the center in {month} — no lessons were held yet this month or every student paid.",
  "Markaz to'laydi": "Center will pay",
  "Markaz to'lagan": "Center paid",
  "Oy yopilganda ustozlarga chiqadi — hali chiqmagan": "Goes to teachers when the month closes — not paid out yet",
  "Kassadan ustozlarga chiqqan pul": "Money paid out of the till to teachers",
  "Qoplanishi kerak": "To be covered",
  "Hali qaytmagan": "Not yet recovered",
  "Oy yopilguncha undirilsa, markaz to'lamaydi": "If collected before the month closes, the center does not pay",
  "Chiqqan puldan hali undirilmagani": "The part of the paid-out money not yet collected",
  "{n} ta dars qoplanadi": "Lessons to be covered: {n}",
  "{n} ta dars qoplangan": "Lessons covered: {n}",
  "Faol emas": "Inactive",
  "Darsga kelmaydi — pul o'zi qaytmaydi": "Not attending — the money won't come back by itself",
  "{month} oyligi hali yopilmagan.": "Payroll for {month} is not closed yet.",
  "Darslar o'tilgan, lekin markaz ustozlarga hali to'lagani yo'q — bu pul oy yopilganda chiqadi. Ya'ni hozir undirilsa, markaz umuman to'lamaydi.": "The lessons were held, but the center has not paid the teachers yet — this money goes out when the month closes. So if it is collected now, the center pays nothing at all.",
  "filtrlangan": "filtered",
  "«Markaz hali olmagan» — jami qarzning markaz ustozlarga chiqarib bo'lgan qismi. «Jami qarzi» esa o'quvchining profilidagi to'liq qarzi: unga markaz qoplamagan oldingi oylar ham kiradi, qaysilari ekani «⧉» nishonida.": "«Center not yet received» is the part of the total debt the center has already paid out to teachers. «Total debt» is the full debt from the student's profile: it also includes earlier months the center did not cover; the «⧉» badge shows which.",
  "Oylik sahifasidagi kartada {amount} turibdi — farqi puli to'liq qaytgan {n} o'quvchi, ular bu ro'yxatda ko'rinmaydi.": "The card on the salary page shows {amount} — the difference is students whose money came back in full (students: {n}); they are not in this list.",
  "{n} ta o'quvchi faol emas (muzlatilgan / chetlatilgan / arxiv). Ular darsga kelmaydi, ya'ni bu pul o'z-o'zidan qaytmaydi — ular bilan bog'lanish kerak.": "Inactive students: {n} (frozen / expelled / archived). They do not attend, so this money won't come back by itself — they need to be contacted.",
  "Ism, telefon yoki ID bo'yicha qidirish…": "Search by name, phone or ID…",
  "Ro'yxat ichidan qidirish": "Search the list",
  "Qoplanadigan oylar": "Months to cover",
  "Markaz qoplagan oylar": "Months covered by the center",
  "Markaz hali olmagan": "Center not yet received",
  "«{query}» bo'yicha hech kim topilmadi.": "No one found for «{query}».",
