  "yana {amount} qarzdor bo'ladi. Kechirish bekor bo'ladi, lekin ro'yxatdan o'chmaydi — kim va nega qaytarib olgani yozib qoladi.": "will owe {amount} again. The write-off is cancelled but stays in the list — who undid it and why is kept.",
  "Kechirishni qaytarib olasizmi?": "Undo the write-off?",
  "Nega qaytarib olinyapti? (majburiy, kamida 5 belgi)": "Why is it being undone? (required, at least 5 characters)",
  "Masalan: Xato qilindi, qarz haqiqiy edi...": "E.g.: a mistake, the debt was real...",
  "Qaytarib olish": "Undo",
  // Payments — debt history and «Qaytariladigan pul» (refunds)
  "Muzlatilganlar": "Frozen",
  "Ketganlar": "Left",
  "30 kungacha": "up to 30 days",
  "31–60 kun": "31–60 days",
  "60 kundan ko'p": "over 60 days",
  "kutilmoqda": "waiting",
  "muddati o'tgan": "term expired",
  "ketgan hisoblanadi": "counted as left",
  "Bank": "Bank",
  "Muzlatilgan o'quvchilarning puli kelishilgan qaytish sanasigacha hisobida turadi. 30 kundan oshgani — shartnoma muddati o'tgan; 60 kundan oshgani tizimda ketgan hisoblanadi.": "The money of frozen students stays on their balance until the agreed return date. Over 30 days means the contract term has expired; over 60 days they count as left in the system.",
  "Statusi faol, lekin hech qaysi guruhda o'qimayotganlar. Guruhga qo'shilsa, pul oylik hisobiga o'tadi.": "Their status is active, but they are not studying in any group. Once added to a group, the money goes toward the monthly fee.",
  "Ketgan, lekin balansida puli qolganlar. Pul so'rov bilan qaytariladi yoki xabar berilgach, muddat o'tganda markaz hisobiga o'tadi.": "Left, but with money still on their balance. The money is refunded on request or, after a notice and once the term expires, moves to the center's account.",
  "So'rov ochilgan kuni o'quvchi balansi 0 bo'ladi. Pul kassadan «Berildi» bosilganda chiqadi. Muddat — 10 bank kuni (shanba, yakshanba va bayramlar sanalmaydi).": "On the day a request is opened the student's balance becomes 0. The money leaves the cash desk when «Handed over» is pressed. The term is 10 bank days (Saturdays, Sundays and holidays are not counted).",
  "{n} kishi — muzlatilgan, guruhsiz yoki ketgan": "People: {n} — frozen, without a group or left",
  "{n} kishi · {over} tasi 30 kundan oshgan": "People: {n} · over 30 days: {over}",
  "{n} kishi · guruhga qo'shilmagan": "People: {n} · not added to a group",
  "{n} kishi · pulini olib ketmagan": "People: {n} · did not take their money",
  "{date} · {days} kun": "{date} · {days} d",
  "berilmagan": "not given",
  "{date} · bot orqali": "{date} · via bot",
  "{date} · qo'ng'iroq qilib aytildi": "{date} · told by phone",
  "muddati o'tdi · {n} bank kuni": "overdue · bank days: {n}",
  "muddati o'tdi": "overdue",
  "bugun oxirgi kun": "last day today",
  "{n} bank kuni qoldi": "Bank days left: {n}",
  "{sum} so'm · {total} ta so'rov": "{sum} UZS · requests: {total}",
  "Hozir kutilayotgan pul qaytarish yo'q.": "There are no pending refunds right now.",
  "Oxirgisi {date} da berilgan.": "The last one was handed over on {date}.",
  "Pul hali berilmagan. Bekor qilinsa, {amount} so'm o'quvchi balansiga qaytadi, bekor qilingan darslar ham joyiga qaytadi.": "The money has not been handed over yet. If cancelled, {amount} UZS go back to the student's balance and the cancelled lessons are restored too.",
  "Shart bajarilgan: xabar {notice}, muddat {term} da tugagan, 30 kun o'tdi.": "Condition met: notice on {notice}, term ended on {term}, 30 days have passed.",
  "naqd": "cash",
  "karta": "card",
  "Oylar bo'yicha qarz": "Debt by month",
  "Har oy oxirida qancha qarz bo'lgan. Kimlar ekanini ko'rish uchun oyni bosing.": "How much debt there was at the end of each month. Click a month to see who owes it.",
  "**Bugungi kunda** shu oydan qolgan qarz — o'sha oyda o'tilgan, lekin hali ham to'lanmagan darslar.": "**As of today**, the debt left over from this month: lessons held that month that are still unpaid.",
  "Keyin to'langan qarz bu yerda qolmaydi. Shuning uchun ustunlar bir-birini takrorlamaydi va qo'shilganda bugungi jami qarzni beradi.": "Debt paid later does not stay here. So the figures do not overlap and add up to today's total debt.",
  "Shu oy qarzi **hozir ham** yopilmagan o'quvchilar soni. To'lab yuborganlar bu yerga kirmaydi.": "The number of students whose debt for this month is **still** open. Those who have paid are not counted.",
  "Bir o'quvchining qarzi bir necha oyga tarqalgan bo'lishi mumkin, shuning uchun bu ustun qo'shilmaydi — «Jami» qatorida takrorsiz son turadi.": "One student's debt can span several months, so this column is not added up: the «Total» row holds the number without repeats.",
  "Tanlangan kesimda ma'lumot yo'q — holat filtrini kengaytirib ko'ring.": "No data for this selection. Try widening the status filter.",
  "hali tugamagan": "not over yet",
  "Oy hali tugamagan. Bu qatordagi raqam har kuni o'zgaradi; oy tugagach qotib qoladi.": "The month is not over yet. The figure in this row changes every day; it freezes when the month ends.",
  "o'tish davri": "transition",
  "Eski tizimdan yangisiga o'tilgan oy. Bu oydagi to'lovlar to'liq kiritilmagan, shuning uchun raqamga boshqa oylar kabi ishonib bo'lmaydi.": "The month of the switch from the old system to the new one. Payments for this month were not entered in full, so the figure cannot be trusted like other months.",
  "to'liq yopilgan": "fully settled",
  "Jami **{amount}** so'm — bu tepadagi «Hozirgi qarz» bilan bir xil raqam, faqat oylarga bo'lingan holda.": "Total **{amount}** UZS — the same figure as «Current debt» above, just split by month.",
  "Ro'yxatda": "Registered",
