  "N oy": "N mo.",
  "Shu oyda hisobdan chiqarilgan qarzlar — pul olinmagan. Ular yuqoridagi ro'yxatda yo'q, chunki bu qarz endi undirilmaydi.": "Debts written off this month: the money was not collected. They are not in the list above because this debt is no longer being collected.",
