  "**{name}**{date} bayrami o'chiriladi. Agar bu bayram tufayli ba'zi guruhlarning tugash sanasi avtomatik uzaytirilgan bo'lsa, ular asl tugash sanasiga qaytariladi. Bu amalni keyinroq qaytarib bo'lmaydi.": "The holiday **{name}**{date} will be deleted. If this holiday automatically extended the end date of some groups, they go back to their original end date. This cannot be undone later.",
