  "O'quvchi guruhdan chiqarilganda, muzlatilganda, chetlatilganda yoki arxivlanganda ko'rsatiladi. Har bir sabab qaysi holatlarda chiqishini belgilab qo'ying.": "Shown when a student is removed from a group, frozen, expelled or archived. Mark the cases in which each reason appears.",
