  "Hozir {n} nafar o'quvchi {pause} va undan ko'p dars qoldirgan. Saqlasangiz, navbatdagi 07:30 yurishda ular pauzaga o'tadi.": "Students who missed {pause} or more lessons in a row: {n}. If you save, the next 07:30 run pauses them.",
