  "Qiymatlar to'g'rilangach, normaning izohi shu yerda ko'rinadi.": "Once the values are fixed, the standard's explanation appears here.",
  "Norma: o'quvchi kuniga kamida {minutes} daqiqa o'quv bo'limida ishlashi yoki {questions} ta savolga javob berishi kerak. Haftada shunday {green} kun bo'lsa — yashil, {yellow} kun bo'lsa — sariq, kamroq bo'lsa — qizil. Norma o'zgartirilsa o'tmish ham yangi norma bilan hisoblanadi.": "Standard: a student should practise at least {minutes} min a day in the learning section or answer at least {questions} questions. {green} such days a week — green, {yellow} — yellow, fewer — red. When the standard changes, the past is also counted by the new standard.",
