  "To'lamagan o'quvchi 2-darsdan qo'yilmasin": "Do not admit unpaid students from lesson 2",
  "1-darsga to'lovsiz kelish mumkin, keyin faqat puli yetgan darslarga qo'yiladi.": "A student may come to lesson 1 without paying, then only to the lessons their money covers.",
  "To'lamaganlar davomatda qulf bilan ko'rinadi va ularni belgilab bo'lmaydi. O'chirilsa, hamma o'quvchi darsga qo'yiladi va to'lov oynasida «qaysi darsgacha yetadi» ko'rinmaydi. Standart holat: yoqilgan. Shartnoma 3.2.": "Unpaid students show in attendance with a lock and cannot be marked. When off, every student is admitted and the payment window does not show «up to which lesson it lasts». Default: on. Contract 3.2.",
  "Darsga kirish uchun eng kam to'lov": "Minimum payment for admission",
  "2-darsdan boshlab darsga kirish uchun oy to'lovining kamida shu qismi to'langan bo'lishi kerak.": "From lesson 2 on, at least this share of the month's payment must be paid to be admitted.",
  "Har guruhda o'sha guruhning 2-darsidan hisoblanadi. 0 qo'yilsa, faqat o'tilgan darslar puli so'raladi. Standart: 50%. 01.11.2026 dan ishlaydi. Shartnoma 3.2.": "Counted in each group from that group's lesson 2. At 0, only the money for lessons already held is asked. Default: 50%. Works from 01.11.2026. Contract 3.2.",
  "Foiz 0 dan 100 gacha bo'lgan butun son bo'lishi kerak": "The percentage must be a whole number from 0 to 100",
  "To'lov tugashidan oldin eslatma": "Reminder before the payment runs out",
  "Puli yetmaydigan birinchi darsdan shuncha kun oldin har kuni 20:00 da Telegram'da eslatma boradi.": "This many days before the first lesson the money does not cover, a reminder goes out in Telegram every day at 20:00.",
  "To'lov kelsa, eslatma to'xtaydi. 0 qo'yilsa, eslatma yuborilmaydi. Standart: 3 kun. Shartnoma 3.7.": "Once a payment arrives, the reminder stops. At 0, no reminder is sent. Default: 3 days. Contract 3.7.",
  "Kun 0 dan 10 gacha bo'lgan butun son bo'lishi kerak": "The days must be a whole number from 0 to 10",
  "O'quvchiga oylik to'lov xabari": "Monthly payment message to the student",
  "Hisob kuni o'quvchiga Telegram'da shu oy uchun qancha to'lash kerakligi yuboriladi.": "On the billing day the student is told in Telegram how much to pay for this month.",
  "To'lamaganlarga oyning 2-darsidan bir kun oldin eslatma ham boradi. Ikkalasi soat 20:00 dagi kunlik xabar bilan keladi. O'chirilsa, bu ikki xabar yuborilmaydi. Standart holat: yoqilgan.": "Those who have not paid also get a reminder one day before the month's lesson 2. Both come with the daily 20:00 message. When off, these two messages are not sent. Default: on.",
  "O'quvchi ketganda": "When a student leaves",
  "Pul qaytarilmaydigan chegara": "No-refund threshold",
  "O'quvchi ketganda oy darslarining shu qismidan ko'pi o'tgan bo'lsa, oy puli qaytarilmaydi.": "If more than this share of the month's lessons has passed when the student leaves, the month's money is not refunded.",
  "Kamroq o'tgan bo'lsa, o'tilmagan darslar puli qaytadi. Guruhdan chiqarish va chetlatishga tegishli. 01.10.2026 dan chiqqanlarga qo'llanadi. Shartnoma 6.2.": "If fewer have passed, the money for lessons not held comes back. Applies to removal from a group and expulsion. Applied to those who left from 01.10.2026. Contract 6.2.",
  "Sinov darsi": "Trial lesson",
  "1 tadan ko'p darsga kelmagan o'quvchi ketsa, oy puli to'liq qaytadi.": "If a student who attended no more than 1 lesson leaves, the month's money is refunded in full.",
  "«Keldi» va «Kechikdi» belgilari sanaladi. Qarzi 0 bo'ladi, ustozga o'sha oy darslari uchun haq yozilmaydi. O'chirilsa, yuqoridagi foiz qoidasi ishlaydi. Standart holat: yoqilgan. Shartnoma 3.5.": "The «Present» and «Late» marks are counted. The debt becomes 0, and the teacher is credited nothing for that month's lessons. When off, the percentage rule above applies. Default: on. Contract 3.5.",
  "Qarz kechirishga ruxsat": "Allow debt write-off",
  "O'chiq bo'lsa, qarzni hech kim kechira olmaydi. Yoqilsa, administrator sabab yozib kechiradi.": "When off, nobody can write off a debt. When on, an administrator writes it off with a reason.",
  "O'chiq (standart holat) bo'lsa, qarz hech qachon kechirilmaydi: guruhdan chiqarish oynasidagi va profildagi kechirish tugmasi ishlamaydi, qarz butun tarixi bilan joyida qoladi. Yoqilsa, administrator sabab yozib va summani qayta terib kechiradi.": "When off (the default), a debt is never written off: the write-off button in the remove-from-group window and on the profile does not work, and the debt stays with its whole history. When on, an administrator writes it off with a reason and by retyping the amount.",
  "Davomat ochilish vaqti": "Attendance opening time",
  "Yangi davomat dars boshlanishidan shuncha oldin ochiladi va dars tugashi bilan yopiladi.": "A new attendance register opens this long before the lesson starts and closes when it ends.",
  "Barcha rollar uchun bir xil. Olingan davomatni markaz rahbari, filial direktori va administrator dars tugagach ham tuzata oladi. Standart: 10 daqiqa.": "The same for every role. The head of the center, the branch director and an administrator can correct a taken register even after the lesson. Default: 10 minutes.",
  "Daqiqa 0 dan 60 gacha bo'lgan butun son bo'lishi kerak": "The minutes must be a whole number from 0 to 60",
  "Faqat markaz rahbari o'zgartira oladi": "Only the head of the center can change this",
