  "Sana va soat, narxni belgilang. Boshqa parametrlarni keyin sozlash mumkin.": "Set the date, time and price. Other settings can be changed later.",
  "Masalan: IELTS Mock — Yanvar 2026": "For example: IELTS Mock — January 2026",
