  "Ro'yxatga olish muddati (ixtiyoriy)": "Registration deadline (optional)",
  "Belgilangan vaqt kelganda ro'yxat avtomatik yopiladi.": "Registration closes automatically at the set time.",
  "0 = bepul": "0 = free",
  "Click/Payme orqali ID'ga to'lanadi": "Paid to the ID via Click/Payme",
  "DaF o'quvchi narxi (ixtiyoriy)": "DaF student price (optional)",
  "Bo'sh = to'liq narx": "Empty = full price",
  "Markazimiz o'quvchilariga chegirmali narx. Chetlatilgan va arxivdagi o'quvchilar to'liq narx to'laydi. Bo'sh qoldirilsa, hamma to'liq narx to'laydi.": "A discounted price for our centre's students. Expelled and archived students pay the full price. If left empty, everyone pays the full price.",
  "Taklif etiladigan darajalar (ixtiyoriy)": "Offered levels (optional)",
  "Tanlangan darajalar botda tugma sifatida chiqadi; ro'yxatdan o'tuvchi bittasini tanlaydi.": "The selected levels appear in the bot as buttons; the person registering picks one.",
  "Bo'limlar va ballar": "Sections and scores",
