  "Nom": "Name",
  "Maks": "Max",
  "O'tish": "Pass",
  "Masalan: Hören": "For example: Hören",
  "Kamida 1 ta bo'lim qoldirish kerak": "At least one section must remain",
  "Bo'lim qo'shish": "Add section",
  "Goethe B1+ modular formati: har bo'lim 100 dan, o'tish 60. O'tish balli ixtiyoriy.": "Goethe B1+ modular format: each section out of 100, pass mark 60. The pass mark is optional.",
  "Bu imtihon bepul bo'ladimi?": "Is this exam free?",
  "Narx kiritilmadi. Agar shunday davom etsangiz, imtihon bepul bo'lib yaratiladi va bot ro'yxatdan o'tganlardan to'lov so'ramaydi.": "No price was entered. If you continue, the exam is created as free and the bot will not ask registrants to pay.",
  "Imtihon pullik bo'lishi kerak bo'lsa — bekor qiling va \"Narx\" maydonini to'ldiring.": "If the exam should be paid, cancel and fill in the \"Price\" field.",
