  "Imtihonni tahrirlash": "Edit exam",
  "Barcha maydonlarni o'zgartirish mumkin. Ishtirokchi bo'lsa, forma o'zgarishi ularning javoblariga ta'sir qilmaydi.": "Every field can be changed. If there are participants, form changes do not affect their answers.",
  "Bir nechta vaqt = botda tanlov. Birinchisi asosiy sana-vaqt.": "Several times = a choice in the bot. The first one is the main date and time.",
