  "Imtihonni o'chirish": "Delete exam",
  "\"{title}\" imtihoni o'chiriladi. Ishtirokchilar va natijalar ham arxivlanadi (yo'qotilmaydi), ularning to'lov havolalari ishlamay qoladi. To'lagan ishtirokchi bo'lsa, avval ularni «Ishtirokchilar» bo'limidan pul qaytarilganini tasdiqlab o'chiring.": "The exam \"{title}\" will be deleted. Participants and results are archived too (not lost), and their payment links stop working. If anyone has paid, first delete them on the \"Participants\" tab, confirming the refund.",
