  "Imtihon holati \"Ro'yxat ochiq\" emas — havola ishlamaydi. Avval imtihonni \"Ro'yxat ochiq\" holatiga o'tkazing.": "The exam status is not \"Registration open\", so the link does not work. First move the exam to \"Registration open\".",
