  "Ishtirokchini qo'lda qo'shish": "Add a participant manually",
  "Telegram botidan o'tmagan ishtirokchini qo'lda yozish. Bunday ishtirokchiga natija Telegramda avtomatik yuborilmaydi.": "Enter a participant who did not register through the Telegram bot. Their result is not sent automatically in Telegram.",
  "Markaz o'quvchisi (ixtiyoriy)": "Centre student (optional)",
  "Ishtirokchi markazimiz o'quvchisi bo'lsa, uni tanlang: ism va telefon kartadan olinadi, DaF chegirmasi qo'llanadi (chetlatilgan va arxivdagilardan tashqari).": "If the participant is a student of our centre, pick them: the name and phone come from the card and the DaF discount applies (except expelled and archived students).",
  "Ishtirokchi markazimiz o'quvchisi bo'lsa, uni tanlang: ism va telefon kartadan olinadi, natijasi o'quvchi profilida ko'rinadi.": "If the participant is a student of our centre, pick them: the name and phone come from the card and the result shows on the student's profile.",
  "Raqam markaz o'quvchisining kartasidagi raqam bo'lsa, o'quvchi avtomatik bog'lanadi.": "If the number matches a centre student's card, the student is linked automatically.",
  "Daraja (ixtiyoriy)": "Level (optional)",
