  // Student portal — FAQ and about
  "Balansni qanday to'ldiraman?": "How do I top up my balance?",
  "«To'lovlar» bo'limiga kiring, summani tanlang va Payme yoki Click orqali to'lang. Balans bir necha soniyada yangilanadi.": "Open “Payments”, choose the amount and pay with Payme or Click. Your balance updates within a few seconds.",
  "Davomat qanday belgilanadi?": "How is attendance marked?",
  "Davomat darsda o'qituvchingiz tomonidan belgilanadi. Uni Bosh sahifada va «Davomat» bo'limida kuzatib borishingiz mumkin.": "Your teacher marks attendance during the lesson. You can follow it on the Home page and in “Attendance”.",
  "Balansim manfiy bo'lsa nima bo'ladi?": "What if my balance is negative?",
  "Manfiy balans qarzdorlikni bildiradi. Darslarni davom ettirish uchun iltimos balansni to'ldiring.": "A negative balance means you have a debt. Please top up your balance to keep attending lessons.",
  "Jadvalim va davomatim qayerda?": "Where are my schedule and attendance?",
  "Bugungi darslaringiz Bosh sahifada, butun hafta «Jadval» bo'limida. Davomat foizi Bosh sahifada, batafsil tarixi «Davomat» bo'limida.": "Today's lessons are on the Home page, the whole week is in “Schedule”. Your attendance rate is on the Home page, the full history is in “Attendance”.",
  "Profil rasmini qanday o'zgartiraman?": "How do I change my profile photo?",
  "Profil sahifasini oching (telefonda «Ko'proq» ichida, kompyuterda yon menyuning tepasida), rasm ustiga bosing va yangi rasm tanlang.": "Open your profile (on a phone under “More”, on a computer at the top of the side menu), tap the photo and choose a new one.",
